cd /tmp && cat > summ.py <<'EOF'
import json, glob, collections, sys
R={}
by_type=collections.defaultdict(list)
for f in glob.glob('export/*.ndjson'):
    for line in open(f):
        r=json.loads(line)
        R[r['id']]=r
        by_type[r['resourceType']].append(r)
def et(r):
    for e in r.get('extension',[]):
        if e['url'].endswith('event-time'): return e['valueDateTime']
    return r.get('period',{}).get('start','') or ''
pats={p['id']:p for p in by_type['Patient']}
# index specimens & accessioning
acc={}
for b in by_type['Basic']:
    d={e['url'].split('/')[-1]:(e.get('valueString') or e.get('valueDateTime') or e.get('valueDate')) for e in b.get('extension',[])}
    acc[d.get('accession')]=(b['id'],d)
def ext(r):
    return {e['url'].split('/')[-1]:(e.get('valueString') or e.get('valueDateTime') or e.get('valueDate')) for e in r.get('extension',[])}
def sub(r):
    s=r.get('subject') or r.get('patient') or r.get('for') or {}
    return s.get('reference','').split('/')[-1]
recs=collections.defaultdict(list)
for r in R.values():
    if r['resourceType'] in ('Patient',): continue
    recs[sub(r)].append(r)
out=sys.stdout
for pid,p in sorted(pats.items()):
    if pid not in recs: continue
    out.write("\n"+"="*100+"\n")
    mrn=p['identifier'][0]['value']
    out.write(f"PATIENT {pid} {p['name'][0]['text']} dob={p['birthDate']} mrn={mrn} gender={p['gender']}\n")
    for r in sorted(recs[pid],key=et):
        t=r['resourceType']; i=r['id']; e=et(r)
        if t=='EpisodeOfCare':
            out.write(f"[{e}] EpisodeOfCare {i} start={r['period']['start']} type={r['type'][0]['text']} status={r['status']}\n")
        elif t=='Condition':
            out.write(f"[{e}] Condition {i} code={r['code']['text']!r} recorded={r.get('recordedDate')} recorder={r.get('recorder',{}).get('display')}\n")
        elif t=='Observation':
            sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            spr=R.get(sp)
            accn=r.get('identifier',[{}])[0].get('value')
            note=' | '.join(n['text'] for n in r.get('note',[]))
            out.write(f"[{e}] Observation {i} {r['code']['text']} coll={r.get('effectiveDateTime')} issued={r.get('issued')} status={r['status']} val={r.get('valueString')!r} acc={accn} spec={sp}\n")
            if note: out.write(f"      note: {note}\n")
            if spr:
                x=ext(spr)
                out.write(f"      SPEC {sp} acc={spr.get('accessionIdentifier',{}).get('value')} coll={spr.get('collection',{}).get('collectedDateTime')} by={spr.get('collection',{}).get('collector',{}).get('display')} label: name={x.get('label-name')} mrn={x.get('label-mrn')} dob={x.get('label-dob')}\n")
            if accn in acc:
                bid,d=acc[accn]
                out.write(f"      ACCN {bid} acc={d.get('accession')} name={d.get('patient-name')} mrn={d.get('patient-mrn')} dob={d.get('patient-dob')} received={d.get('received')}\n")
        elif t=='MedicationAdministration':
            note=' | '.join(n['text'] for n in r.get('note',[]))
            perf=[x.get('actor',{}).get('display') for x in r.get('performer',[])]
            out.write(f"[{e}] MedAdmin {i} status={r['status']} eff={r.get('effectiveDateTime')} dose={r.get('dosage',{}).get('text')} med={(r.get('medicationCodeableConcept') or {}).get('text')} perf={perf}"+(f" note={note}" if note else "")+"\n")
        elif t=='MedicationDispense':
            note=' | '.join(n['text'] for n in r.get('note',[]))
            out.write(f"[{e}] MedDispense {i} med={(r.get('medicationCodeableConcept') or {}).get('text')} qty={r.get('quantity')} days={r.get('daysSupply')} handed={r.get('whenHandedOver')} dosage={[d.get('text') for d in r.get('dosageInstruction',[])]}"+(f" note={note}" if note else "")+"\n")
        elif t=='DocumentReference':
            x=ext(r)
            out.write(f"[{e}] DocRef {i} type={(r.get('type') or {}).get('text')} date={r.get('date')} author={[a.get('display') for a in r.get('author',[])]} role={x.get('author-role')}\n")
            out.write("      TEXT: "+(r.get('description','').replace('\n','\n            '))+"\n")
        elif t=='AllergyIntolerance':
            out.write(f"[{e}] Allergy {i} code={(r.get('code') or {}).get('text')} reaction={json.dumps(r.get('reaction'))}\n")
        elif t=='Task':
            out.write(f"[{e}] Task {i} status={r['status']} code={r['code']['coding'][0]['code']} focus={r.get('focus')} desc={r.get('description')}\n")
        else:
            out.write(f"[{e}] {t} {i} {json.dumps(r)[:300]}\n")
EOF
python3 summ.py > all.txt; wc -l all.txt

