print("--- Observation ID checks ---")
for o in sorted(by['Observation'],key=lambda x:x.get('effectiveDateTime','')):
    subj=o['subject']['reference'].split('/')[-1]
    p=pats[subj]; pm=p['identifier'][0]['value']; pd=p['birthDate']
    sp=R.get(o.get('specimen',{}).get('reference','').split('/')[-1])
    a=o.get('identifier',[{}])[0].get('value')
    prob=[]
    if sp:
        x=ext(sp)
        if x.get('label-mrn')!=pm or x.get('label-dob')!=pd: prob.append(f"SPECLABEL {x.get('label-name')}/{x.get('label-mrn')}/{x.get('label-dob')}")
    else: prob.append("NOSPEC")
    if a in acc:
        _,d=acc[a]
        if d.get('patient-mrn')!=pm or d.get('patient-dob')!=pd: prob.append(f"ACCN {d.get('patient-name')}/{d.get('patient-mrn')}/{d.get('patient-dob')}")
        if sp and (ext(sp).get('label-mrn')!=d.get('patient-mrn') or ext(sp).get('label-dob')!=d.get('patient-dob')): prob.append("SPEC-vs-ACCN mismatch")
    else: prob.append("NO ACCN ENTRY")
    if prob: print(o['id'],o['code']['text'],o.get('effectiveDateTime'),subj,p['name'][0]['text'],'|','; '.join(prob))
print()
print("--- orphan accession entries (no observation) ---")
usedacc={o.get('identifier',[{}])[0].get('value') for o in by['Observation']}
for a,(bid,d) in acc.items():
    if a not in usedacc: print(bid,a,d)
print("--- specimens with no observation ---")
