for s in by['Specimen']:
    if s['id'] not in usedspec: print(s['id'], s.get('accessionIdentifier'), ext(s))
print("--- non-final observations ---")
for o in by['Observation']:
    if o['status']!='final': print(o['id'],o['status'],o['code']['text'],o.get('effectiveDateTime'),o['subject'],[n['text'] for n in o.get('note',[])])
